import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import ChatInterface from './ChatInterface/ChatInterface';
import ProcessVisualization from './ProcessVisualization/ProcessVisualization';

// Basic ProcessPage component
const ProcessPage = () => {
  let { processId } = useParams();
  const [processData, setProcessData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchProcessDetails = async () => {
    if (!processId) return;
    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/processes/${processId}`);
      if (!response.ok) {
        if (response.status === 404) {
          throw new Error('Process not found.');
        } else {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
      }
      const data = await response.json();
      setProcessData(data);
    } catch (err) {
      console.error(`Failed to fetch process ${processId}:`, err);
      setError(err.message || 'Failed to fetch process details.');
      setProcessData(null);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProcessDetails();
  }, [processId]); // Re-fetch if processId changes

  // Callback for ChatInterface to notify that process data might have been updated by an AI operation
  const handleProcessDataNeedsUpdate = () => {
    console.log("ProcessPage: Received notification to update process data. Re-fetching...");
    fetchProcessDetails(); // Re-fetch the process data
  };

  const pageStyle = {
    display: 'flex',
    flexDirection: 'row',
    height: 'calc(100vh - 100px)', // Adjust based on header height, approx
    width: '100%',
    padding: 'var(--spacing-unit, 16px)',
    gap: 'var(--spacing-unit, 16px)',
    boxSizing: 'border-box' // Ensure padding and gap are included in width/height calculations
  };

  const panelStyle = {
    flex: '1 1 50%', // Each panel takes 50% of the width, can grow and shrink
    overflow: 'auto', // Add scroll if content overflows
    // border: '1px solid blue' // For debugging layout
  };

  if (isLoading) {
    return <div style={{ padding: '20px', textAlign: 'center' }}>Loading process details...</div>;
  }

  if (error) {
    return <div style={{ padding: '20px', color: 'red', textAlign: 'center' }}>Error: {error}</div>;
  }

  if (!processData) {
    // This case might be hit if fetch completes with no error but data is still null (e.g. API returns empty for some reason)
    return <div style={{ padding: '20px', textAlign: 'center' }}>Process data could not be loaded or found.</div>;
  }

  return (
    <div style={pageStyle}>
      <div style={panelStyle}>
        <ChatInterface 
          processId={processId} 
          processData={processData} 
          onProcessDataUpdate={handleProcessDataNeedsUpdate} // Pass the callback
        />
      </div>
      <div style={panelStyle}>
        <ProcessVisualization processId={processId} processData={processData} />
      </div>
    </div>
  );
};

export default ProcessPage;
